&lt;p style="text-align:center"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:11pt"&gt;###&lt;/span&gt;&lt;span style="font-size:11pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
