&lt;div class="OutlineElement Ltr SCXW217080013 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;At its December meeting, the Hospital Association of Oregon Board of Trustees selected its officers,&amp;nbsp;whose collective&amp;nbsp;expertise&amp;nbsp;will help guide the organization&rsquo;s strategic priorities and support hospitals at a critical moment for health care in Oregon.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW217080013 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;Jennifer Burrows, chief executive of Providence Oregon, will continue to serve as Chair through 2027. Cheryl Nester Wolfe, president and CEO of Salem Health, will continue to serve as Past-Chair.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW217080013 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;A strong advocate for rural hospitals, Jeremy Davis, who is the president and CEO of Grand Ronde Hospital, was elected to serve as Chair-Elect and Chair the Public Policy Committee.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW217080013 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;The Membership elected seven Member&amp;nbsp;Trustees,&amp;nbsp;and the Board elected two Non-member Trustees. They include:&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;ul&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;strong&gt;Jennifer Burrows&lt;/strong&gt;, chief executive of Providence Oregon, who will continue serving as a Member Trustee.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;strong&gt;Cheryl Nester Wolfe&lt;/strong&gt;, president and CEO of Salem Health, who will continue serving as a Member Trustee.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Jeremy Davis&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, president and CEO of Grande Ronde Hospital, who will continue serving as a Member Trustee.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Jonathan Avery&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, senior vice president and chief operating officer at Legacy Health&lt;/span&gt;&lt;span style="font-family:arial,arial_embeddedfont,arial_msfontservice,sans-serif"&gt;&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, who will continue serving as a Member Trustee.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Brooke Baldwin&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, senior vice president and chief nursing executive at OHSU Health, who will serve as the Non-Member Trustee - Nurse Executive.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;strong&gt;Marty Cahill&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, president and CEO of Samaritan Health Services, who will continue serving as a Member Trustee.&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Dr. Jason Gray&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, chief medical officer and vice president of medical affairs at CHI Mercy Health, who will serve as the Non-Member Trustee - Physician Executive.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Kyle King&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, president of Adventist Health, who will continue serving as a Member Trustee.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
     &lt;li&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;&lt;span style="font-size:16px"&gt;&lt;strong&gt;Erik Thorsen&lt;/strong&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;, president and CEO of Columbia Memorial Hospital, who will continue serving as a Member Trustee.&nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;

&lt;div class="OutlineElement Ltr SCXW217080013 BCX8" style="-webkit-user-drag: none; -webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; user-select: text; clear: both; cursor: text; overflow: visible; position: relative; direction: ltr; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;span style="font-size:16px"&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif"&gt;The&amp;nbsp;Member Trustees will serve through Dec. 31, 2027.&amp;nbsp;Gray&rsquo;s term is through&amp;nbsp;Dec.&amp;nbsp;31, 2026, and Baldwin&rsquo;s term, through Dec. 31, 2029.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

