&lt;p&gt;&lt;a href="mailto:marshasills@oha.oregon.gov" rel="noopener" style="color: rgb(6, 66, 118); text-decoration-line: none; text-size-adjust: 100%;" target="_blank"&gt;marshasills@oha.oregon.gov&lt;/a&gt;, 971-240-3344&amp;nbsp;&lt;/p&gt;
